import { z } from 'zod'
import { db } from '../db.js'
import { logger } from '../logger.js'
import type { JobHandler } from '../types.js'

const Data = z.object({ invoiceId: z.string().uuid(), orgId: z.string().uuid(), paidAt: z.string().datetime() })

export const deliverInvoicePaid: JobHandler = async (job) => {
  const { invoiceId, orgId, paidAt } = Data.parse(job.data)
  const org = await db.query.orgs.findFirst({ where: (o, { eq }) => eq(o.id, orgId) })
  if (!org?.callbackUrl) return

  const invoice = await db.query.invoices.findFirst({
    where: (i, { and, eq }) => and(eq(i.id, invoiceId), eq(i.orgId, orgId)),
  })
  if (!invoice) return

  const body = JSON.stringify({
    id: `evt_${job.id}`,
    type: 'invoice.paid',
    createdAt: new Date().toISOString(),
    data: { invoiceId, number: invoice.number, amountCents: invoice.totalCents, currency: invoice.currency, paidAt },
  })

  const res = await fetch(org.callbackUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/json', 'user-agent': 'acme-events/1' },
    body,
    signal: AbortSignal.timeout(10_000),
  })
  if (!res.ok) {
    // throw so the queue retries with backoff
    throw new Error(`invoice.paid delivery failed with status ${res.status}`)
  }
  logger.info({ orgId, invoiceId, jobId: job.id, status: res.status }, 'invoice.paid delivered')
}

