function slugify(input: string) {
  return input
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60)
}

export function pdfFilename(invoice: Pick<Invoice, 'number'>, client: Pick<Client, 'name'>) {
  const parts = [slugify(invoice.number), slugify(client.name)].filter(Boolean)
  return `${parts.join('_') || 'invoice'}.pdf`
}

