export type VoidOptions = { reason?: string; yes?: boolean }

export async function runVoid(id: string, opts: VoidOptions) {
  const invoice = await api.invoices.get(id)

  if (!opts.yes) {
    if (!process.stdin.isTTY) {
      logger.error('Refusing to void without confirmation in a non-interactive shell. Pass --yes.')
      process.exitCode = 2
      return
    }
    const ok = await confirm({ message: `Void invoice ${invoice.number}? This cannot be undone.`, initialValue: false })
    if (isCancel(ok) || !ok) {
      cancel('Nothing voided.')
      return
    }
  }

  await api.invoices.void(id, { reason: opts.reason })
  logger.success(`Voided ${invoice.number}`)
}

