const MIN_MAJOR = 20

export function checkRuntime(): boolean {
  const major = Number(process.versions.node.split('.')[0])
  if (Number.isFinite(major) && major >= MIN_MAJOR) return true
  const yellow = (s: string) => (process.stderr.isTTY ? `\x1b[33m${s}\x1b[39m` : s)
  process.stderr.write(
    yellow(`This tool needs runtime version ${MIN_MAJOR} or newer; you are on ${process.version}.\n`) +
      'Install a newer LTS release and try again.\n',
  )
  process.exitCode = 1
  return false
}

